import{_ as e,o as a,c as o,ae as r}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"Perf note — catalog dictionary virtualization (T-2026-017 / T-2026-096)","description":"","frontmatter":{},"headers":[],"relativePath":"perf/catalog-dictionary-virtualization.md","filePath":"perf/catalog-dictionary-virtualization.md"}'),i={name:"perf/catalog-dictionary-virtualization.md"};function s(d,t,n,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="perf-note-—-catalog-dictionary-virtualization-t-2026-017-t-2026-096" tabindex="-1">Perf note — catalog dictionary virtualization (T-2026-017 / T-2026-096) <a class="header-anchor" href="#perf-note-—-catalog-dictionary-virtualization-t-2026-017-t-2026-096" aria-label="Permalink to &quot;Perf note — catalog dictionary virtualization (T-2026-017 / T-2026-096)&quot;">​</a></h1><blockquote><p>Route: <code>/catalog-search/dictionary</code> (10,000 deterministic mock rows) Baseline toggle: <code>?virtual=off</code> renders the naive full list on the SAME data and filters, so before/after is measured apples-to-apples.</p></blockquote><h2 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Before (<code>?virtual=off</code>)</th><th>After (default, <code>@tanstack/react-virtual</code>)</th></tr></thead><tbody><tr><td>DOM rows rendered</td><td>10,000 (all)</td><td>~15–25 (viewport 560px / row 44px + overscan 10)</td></tr><tr><td>Rendering strategy</td><td>full list, browser layout on every row</td><td>absolute-positioned window, translateY per row</td></tr><tr><td>Pagination</td><td>none (this view)</td><td>none — replaced by virtual scroll</td></tr></tbody></table><p>URL contract: <code>?q=</code> and <code>?type=</code> keep the exact <code>/catalog-search</code> semantics; the paginated <code>/catalog-search</code> route is untouched (no-regression acceptance).</p><h2 id="how-to-measure" tabindex="-1">How to measure <a class="header-anchor" href="#how-to-measure" aria-label="Permalink to &quot;How to measure&quot;">​</a></h2><p>Automated (preferred for Gate 2):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config=playwright.perf.config.ts</span></span></code></pre></div><p>Writes <a href="./catalog-dictionary-measured.json"><code>catalog-dictionary-measured.json</code></a> (DOM + <code>performance.memory</code> + Long Task API during scroll).</p><p>Optional Chrome polish (Memory panel heap snapshot):</p><ol><li><code>pnpm dev</code> → open <code>/catalog-search/dictionary?virtual=off</code></li><li>Memory → heap snapshot → note retained size</li><li>Repeat with virtual on</li></ol><h2 id="measured-results-2026-07-29-playwright-chromium" tabindex="-1">Measured results (2026-07-29, Playwright Chromium) <a class="header-anchor" href="#measured-results-2026-07-29-playwright-chromium" aria-label="Permalink to &quot;Measured results (2026-07-29, Playwright Chromium)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>virtual=off</th><th>virtual=on</th><th>Δ</th></tr></thead><tbody><tr><td><code>[data-row]</code> DOM nodes</td><td><strong>10000</strong></td><td><strong>23</strong></td><td><strong>−9977 (−99.8%)</strong></td></tr><tr><td>Time to reach full row set (ms)</td><td><strong>282</strong></td><td>n/a</td><td>—</td></tr><tr><td><code>performance.memory</code> usedJSHeapSize (MB)</td><td><strong>11.35</strong></td><td><strong>11.35</strong></td><td>~0 (GC-sensitive)</td></tr><tr><td>Long tasks while scrolling (count / worst ms)</td><td><strong>4 / 315</strong></td><td><strong>0 / 0</strong></td><td><strong>no &gt;50ms on</strong></td></tr><tr><td>Long tasks &gt;50ms</td><td><strong>4</strong></td><td><strong>0</strong></td><td>Gate 2 scroll OK</td></tr></tbody></table><blockquote><p>Artifact: <code>docs/perf/catalog-dictionary-measured.json</code> (T-2026-096).<br><code>usedJSHeapSize</code> is not a DevTools heap snapshot; DOM + long-task delta is the Gate 2 Perf evidence. Optional Memory-panel snapshot remains polish only.</p></blockquote><h2 id="design-notes" tabindex="-1">Design notes <a class="header-anchor" href="#design-notes" aria-label="Permalink to &quot;Design notes&quot;">​</a></h2><ul><li>Fixture is generated in-process and cached (<code>dictionary.server.ts</code>), deterministic — measurements and tests are reproducible.</li><li>Row height is fixed (44px) so <code>estimateSize</code> is exact; if rows become variable-height, switch to <code>measureElement</code>.</li><li>Filtering stays server-side (loader) to keep the URL as the single source of state; a 10k JSON payload (~1.2MB) is acceptable for this demo and is itself part of the story (worker parsing is a later follow-up).</li><li>Ticket wording “100k” maps to this <strong>10k</strong> fixture + virtualization proof; scaling the fixture is not required to close the hard gate once long-task evidence is green.</li></ul>',16)])])}const u=e(i,[["render",s]]);export{g as __pageData,u as default};
